<?php
namespace Database\Seeders;
use Illuminate\Database\Seeder;use App\Models\User;use App\Features\Post\Models\Post;
class DatabaseSeeder extends Seeder{public function run():void{$admin=User::firstOrCreate(['email'=>'admin@blogverse.test'],['name'=>'Administrator','username'=>'admin','password'=>'password123','role'=>'admin']);$writer=User::firstOrCreate(['email'=>'writer@blogverse.test'],['name'=>'Penulis Demo','username'=>'writer','password'=>'password123','role'=>'member','bio'=>'Menulis tentang teknologi dan produktivitas.']);if($writer->posts()->count()===0){$samples=[['title'=>'Memulai Perjalanan di Dunia Teknologi','category'=>'Teknologi','excerpt'=>'Panduan awal memahami perkembangan teknologi dan dampaknya dalam kehidupan.','content'=>"# Memulai Perjalanan di Dunia Teknologi\n\nTeknologi berkembang dengan sangat cepat. Memahami dasar-dasarnya membantu kita mengambil keputusan yang lebih baik.\n\n## Mulai dari rasa ingin tahu\n\nPilih satu bidang, pelajari konsep dasarnya, lalu bangun proyek kecil untuk menguji pemahaman."],['title'=>'Belajar Efektif dengan Kebiasaan Kecil','category'=>'Pendidikan','excerpt'=>'Konsistensi dan strategi sederhana dapat meningkatkan kualitas belajar.','content'=>"# Belajar Efektif\n\nBelajar bukan sekadar menghabiskan waktu di depan buku. Buat target yang terukur, gunakan jeda teratur, dan evaluasi hasilnya."],['title'=>'Produktivitas Tanpa Burnout','category'=>'Gaya Hidup','excerpt'=>'Atur prioritas dan energi agar pekerjaan tetap berkelanjutan.','content'=>"# Produktivitas Tanpa Burnout\n\nProduktivitas yang sehat berangkat dari prioritas. Kerjakan tugas penting lebih dulu dan sisihkan waktu untuk beristirahat."]];foreach($samples as $i=>$sample)$writer->posts()->create($sample+['slug'=>Post::uniqueSlug($sample['title']),'is_published'=>true,'published_at'=>now()->subDays($i)]);}}}
